using marble_physics::Mem;
using marble_physics::PLAYER;

// object fields
static const uint8_t PX = 0x0c, PY = 0x10, PZ = 0x14, SLOT = 0x18, IDX = 0x19, STATE = 0x1a;
static const uint8_t ZONE = 0x1b, VISIBLE = 0x1c, SX = 0x1e, SY = 0x20, MASKS = 0x38;
static const uint8_t ANIM = 0x5a, SHARDS = 0x62, SHARDS_ON = 0x67;
static const uint8_t ANGER = 0x6c, NODE = 0x6e;
static const uint8_t L_TICK = 0x24, L_SCREEN = 0x28, L_MASKS = 0x2c, L_NEXT = 0x4a;
static const uint8_t L_BAND_LO = 0x52, L_BAND_HI = 0x54, L_PREY = 0x56, L_CURSOR = 0x58;
static const uint8_t MASK_BYTES = 30;
static const uint32_t RNG = 0x4003a6;
static const uint16_t RNG_TICK = 0x100;
static const uint32_t LIST = 0x4003bc, ENTRIES = 0x4001dc;  // draw list bytes, entries
static const uint8_t ENTRY_SIZE = 14, LIST_MAX = 31, LIST_END = 0xff;
static const uint8_t TYPE_STEELIE = 2, TYPE_SLINKY = 4;
static const uint32_t STEELIE_FRAME = 0x21f36;
static const uint8_t SHATTERING = 2;
static const uint8_t ST_HIDDEN = 7, ST_DISSOLVE = 9;
static const uint8_t RACES = 6, RACE_SILLY = 4;
static const int16_t SWEEP_STEP = 4;  // marble_mo.SWEEP_STEP
static const uint16_t EAT_TICKS = 600;

static uint8_t ram[marble_physics::RAM_SIZE];

static uint32_t steelie(uint8_t i) {
  return marble_enemies::STEELIES + marble_enemies::STEELIE_SIZE * i;
}

static uint32_t slinky(uint8_t i) {
  return marble_enemies::SLINKIES + marble_enemies::SLINKY_SIZE * i;
}

static void loadRam(const MarbleSlinkySegment &seg) {
  memset(ram, 0, sizeof(ram));
  for (uint8_t i = 0; i < seg.nram; i++) {
    const MarbleSlinkyRam &r = seg.ram[i];
    memcpy(ram + (r.addr - marble_physics::RAM_BASE), r.bytes, r.len);
  }
}

// draw list entry k in link order: type << 8 | index, -1 past the end
static int16_t entryAt(const Mem &m, uint8_t k) {
  if (k >= LIST_MAX || m.rb(LIST + k) == LIST_END) { return -1; }
  const uint32_t e = ENTRIES + ENTRY_SIZE * m.rb(LIST + k);
  return (int16_t)(m.rb(e) << 8 | m.rb(e + 1));
}

static bool listed(const Mem &m, uint8_t type, uint8_t idx) {
  for (uint8_t k = 0; entryAt(m, k) >= 0; k++) {
    if (entryAt(m, k) == (type << 8 | idx)) { return true; }
  }
  return false;
}

static uint8_t listedCount(const Mem &m, uint8_t type, uint8_t idx) {
  uint8_t n = 0;
  for (uint8_t k = 0; entryAt(m, k) >= 0; k++) { n += entryAt(m, k) == (type << 8 | idx); }
  return n;
}

// player frame header drawn from +0x5a (states 1, 2, 5, 9) and the shard overlay +0x62
static uint32_t playerHdr(const Mem &m) {
  const uint8_t st = marble_physics::state(m);
  const bool drawn = st == marble_physics::DIZZY || st == marble_physics::BROKEN ||
                     st == marble_physics::EATEN || st == ST_DISSOLVE;
  return m.rb(PLAYER + VISIBLE) && drawn ? m.roml(m.rl(PLAYER + ANIM)) : 0;
}

static uint32_t shardHdr(const Mem &m, uint32_t a, bool shown) {
  return shown && m.rb(a + SHARDS_ON) ? m.roml(m.rl(a + SHARDS)) : 0;
}

static bool steelieShown(const Mem &m, uint8_t i) {
  const uint32_t a = steelie(i);
  return m.rb(a + SLOT) && m.rb(a + VISIBLE) && listed(m, TYPE_STEELIE, i);
}

static uint32_t steelieHdr(const Mem &m, uint8_t i) {
  if (!steelieShown(m, i)) { return 0; }
  const uint32_t a = steelie(i);
  return m.rb(a + SLOT) == SHATTERING ? m.roml(m.rl(a + ANIM)) : STEELIE_FRAME;
}

static const char *playerDiff(const Mem &m, const MarbleSlinkyTick &t) {
  if (marble_physics::x(m) != t.x) { return "player x"; }
  if (marble_physics::y(m) != t.y) { return "player y"; }
  if (marble_physics::z(m) != t.z) { return "player z"; }
  if (marble_physics::state(m) != t.state) { return "player state"; }
  if (m.rb(PLAYER + VISIBLE) != t.vis) { return "player vis"; }
  if (m.sw(PLAYER + SX) != t.sx || m.sw(PLAYER + SY) != t.sy) { return "player sx/sy"; }
  if (m.rl(PLAYER + ANIM) != t.anim) { return "player anim"; }
  if (playerHdr(m) != t.frame_hdr) { return "player frame"; }
  if (shardHdr(m, PLAYER, m.rb(PLAYER + VISIBLE)) != t.shard_hdr) { return "player shards"; }
  if (memcmp(ram + (PLAYER + MASKS - marble_physics::RAM_BASE), t.mask, MASK_BYTES)) {
    return "player mask";
  }
  if (m.rw(RNG) != t.rng) { return "rng"; }
  return nullptr;
}

static const char *steelieDiff(const Mem &m, uint8_t i, const MarbleSlinkySteelie &s) {
  const uint32_t a = steelie(i);
  if (m.rb(a + SLOT) != s.live) { return "steelie live"; }
  if (m.rb(a + STATE) != s.mode) { return "steelie mode"; }
  if (m.rb(a + VISIBLE) != s.vis) { return "steelie vis"; }
  if (m.sl(a + PX) != s.x || m.sl(a + PY) != s.y || m.sl(a + PZ) != s.z) {
    return "steelie position";
  }
  if (m.sw(a + SX) != s.sx || m.sw(a + SY) != s.sy) { return "steelie sx/sy"; }
  if (m.rl(a + ANIM) != s.anim) { return "steelie anim"; }
  if (steelieHdr(m, i) != s.frame_hdr) { return "steelie frame"; }
  if (shardHdr(m, a, steelieShown(m, i)) != s.shard_hdr) { return "steelie shards"; }
  if (m.rw(a + ANGER) != s.anger) { return "steelie anger"; }
  if (m.rl(a + NODE) != s.node) { return "steelie node"; }
  if (memcmp(ram + (a + MASKS - marble_physics::RAM_BASE), s.mask, MASK_BYTES)) {
    return "steelie mask";
  }
  return nullptr;
}

// slinky frame drawn: rl(cursor) while live and listed, else 0
static uint32_t slinkyHdr(const Mem &m, uint8_t i) {
  const uint32_t a = slinky(i);
  return m.rb(a + SLOT) && listed(m, TYPE_SLINKY, i) ? m.roml(m.rl(a + L_CURSOR)) : 0;
}

static const char *slinkyDiff(const Mem &m, uint8_t i, const MarbleSlinkyObj &s) {
  const uint32_t a = slinky(i);
  if (m.rb(a + SLOT) != s.live) { return "slinky live"; }
  if (m.rb(a + STATE) != s.state) { return "slinky state"; }
  if (m.sl(a + PX) != s.x || m.sl(a + PY) != s.y) { return "slinky x/y"; }
  if (m.sl(a + PZ) != s.z) { return "slinky z"; }
  if (m.sw(a + L_SCREEN) != s.sx || m.sw(a + L_SCREEN + 2) != s.sy) { return "slinky sx/sy"; }
  if (m.rl(a + L_TICK) != s.tick) { return "slinky tick"; }
  if (m.rl(a + L_NEXT) != s.next) { return "slinky next"; }
  if (m.rw(a + L_PREY) != s.prey) { return "slinky prey"; }
  if (m.rl(a + L_CURSOR) != s.cursor) { return "slinky cursor"; }
  if (slinkyHdr(m, i) != s.frame_hdr) { return "slinky frame"; }
  if (memcmp(ram + (a + L_MASKS - marble_physics::RAM_BASE), s.mask, MASK_BYTES)) {
    return "slinky mask";
  }
  return nullptr;
}

static const char *listDiff(const Mem &m, const MarbleSlinkySegment &seg,
                            const MarbleSlinkyTick &t) {
  for (uint8_t k = 0; k < t.nlist; k++) {
    const MarbleSlinkyEntry &e = seg.list[t.lfirst + k];
    if (entryAt(m, k) != (e.type << 8 | e.index)) { return "draw list"; }
  }
  return entryAt(m, t.nlist) < 0 ? nullptr : "draw list length";
}

// One main loop tick as marble_slinky.py replays it: 0x400010 and the camera long are inputs,
// then 0x1344c, band spawns (old camera still stored, as 0x13ee6), player 0x251de, steelies
// 0x158cc, slinkies 0x1493c, slots 0x12fd0, rng, the 0x26f3e sort.
static void mainTick(Mem &m, int8_t c6, int8_t c7, uint32_t camera, uint32_t frames) {
  m.wl(marble_physics::FRAMES, frames);
  marble_objects::applyQueued(m);
  const int16_t old = m.sw(marble_physics::CAMERA);
  if ((int16_t)camera != old) { marble_objects::cameraBands(m, old, (int16_t)camera); }
  m.wl(marble_physics::CAMERA_L, camera);
  marble_physics::tick(m, c6, c7);
  marble_enemies::update(m);
  marble_objects::update(m);
  marble_rng::rng(m, RNG_TICK);
  marble_drawlist::sort(m);
}

static void test_replay_slinkies(void) {
  for (uint8_t s = 0; s < MARBLE_SLINKIES_SEGMENTS; s++) {
    const MarbleSlinkySegment &seg = marble_slinkies_segments[s];
    loadRam(seg);
    Mem m(ram, seg.race);

    for (uint16_t k = 0; k < seg.nticks; k++) {
      const MarbleSlinkyTick &t = seg.ticks[k];
      mainTick(m, t.c6, t.c7, t.camera, t.frames);
      const char *bad = playerDiff(m, t);
      int8_t which = -1;
      for (uint8_t i = 0; i < marble_enemies::NSTEELIES && !bad; i++) {
        bad = steelieDiff(m, i, t.s[i]);
        which = (int8_t)i;
      }
      for (uint8_t i = 0; i < marble_enemies::NSLINKIES && !bad; i++) {
        bad = slinkyDiff(m, i, t.l[i]);
        which = (int8_t)i;
      }
      if (!bad) {
        bad = listDiff(m, seg, t);
        which = -1;
      }
      if (!bad) { continue; }

      char msg[160];
      snprintf(msg, sizeof(msg), "segment %d (race %d frame %u) tick %d: object %d %s differs",
               s, seg.race, (unsigned)seg.frame, k, which, bad);
      TEST_FAIL_MESSAGE(msg);
    }
  }
}

// ---------------------------------------------------------------- slinky objects

// One MO as the published state draws it: race pixel top left, height, MO code (0 for a frame
// column), hflip, priority (mask)
struct DrawnMo {
  int16_t x, top;
  uint8_t h;
  uint16_t code;
  bool flip, mask;
};

static const uint8_t PAL_SLINKY = 4;  // MO palette set of the slinky frames
static const uint8_t MOS_MAX = 32;    // MOs of one slinky: frame columns, masks

// MOs of slinky i in v: its object at the origin (+0x28, top + ARCADE_H - +0x2a) and its masks
static uint8_t slinkyMos(const Mem &m, const marble_video::VideoState &v, uint8_t i, int16_t top,
                         DrawnMo *out) {
  using namespace marble_video;
  const uint32_t a = slinky(i);
  const int16_t ox = m.sw(a + L_SCREEN);
  const int16_t oy = (int16_t)(top + ARCADE_H - m.sw(a + L_SCREEN + 2));
  const MarbleSpriteSet &ds = marble_physics::deathSet();
  uint8_t k = 0;
  for (uint8_t j = 0; j < v.n; j++) {
    const Obj &o = v.objs[j];
    if (o.x != ox || o.y != oy || o.set != (SET_DEATH | SET_SLINKY)) { continue; }
    const MarbleSpriteFrame &f = ds.frames()[o.frame];
    for (uint8_t c = 0; c < f.ncols && k < MOS_MAX; c++) {
      const MarbleSpriteCol &col = ds.cols()[f.first + c];
      out[k++] = {(int16_t)(o.x + col.x), (int16_t)(o.y + col.y), (uint8_t)(col.h & 0x7f), 0,
                  (col.h & 0x80) != 0, false};
    }
    for (uint8_t q = o.mask; q < o.mask + o.nmask && k < MOS_MAX; q++) {
      const Mask &e = v.masks[q];
      out[k++] = {(int16_t)(o.x + e.dx), (int16_t)(o.y + e.dy), (uint8_t)(((e.code >> 11) & 7) + 1),
                  (uint16_t)(e.code & 0x7ff), (e.code & 0x8000) != 0, true};
    }
  }
  return k;
}

// MO RAM words of d (MO x = race x + 24, MO y counts up: top line = 256 - MO y - 8 h)
static MarbleSlinkyMo moWords(const DrawnMo &d, int16_t top) {
  const uint16_t y = (uint16_t)(top + 256 - d.top - 8 * d.h);
  const uint16_t x = (uint16_t)(d.x + 24);
  return {(uint16_t)(((y << 5) & 0x3fe0) | (d.flip ? 0x8000 : 0) | (d.h - 1)),
          (uint16_t)(d.code | (d.mask ? 0 : PAL_SLINKY << 11)),
          (uint16_t)(((x << 5) & 0x3fe0) | (d.mask ? 0x8000 : 0))};
}

// Published slinkies (build at the arcade cull) against the slinky MOs MAME emitted in every
// fixture tick: frame columns (position, height, flip, palette set 4), masks
static void test_slinky_objects(void) {
  uint16_t drawn = 0, masked = 0;
  for (uint8_t sg = 0; sg < MARBLE_SLINKIES_SEGMENTS; sg++) {
    const MarbleSlinkySegment &seg = marble_slinkies_segments[sg];
    loadRam(seg);
    Mem m(ram, seg.race);
    const int16_t descTop = m.desc().top;

    for (uint16_t k = 0; k < seg.nticks; k++) {
      const MarbleSlinkyTick &t = seg.ticks[k];
      mainTick(m, t.c6, t.c7, t.camera, t.frames);
      marble_video::VideoState v = {};
      v.level = seg.race;
      TEST_ASSERT_TRUE(marble_drawlist::build(m, (int16_t)t.camera, 0, v) <= marble_video::OBJS);
      const int16_t top = (int16_t)((int16_t)t.camera - descTop);

      for (uint8_t i = 0; i < marble_enemies::NSLINKIES; i++) {
        const MarbleSlinkyObj &s = t.l[i];
        char msg[120];
        snprintf(msg, sizeof(msg), "segment %d tick %d slinky %d (state %d)", sg, k, i, s.state);
        DrawnMo got[MOS_MAX];
        const uint8_t n = slinkyMos(m, v, i, top, got);
        TEST_ASSERT_EQUAL_UINT8_MESSAGE(s.n, n, msg);
        for (uint8_t j = 0; j < n; j++) {
          const MarbleSlinkyMo &e = seg.mos[s.first + j];
          const MarbleSlinkyMo w = moWords(got[j], top);
          TEST_ASSERT_EQUAL_HEX16_MESSAGE(e.w0, w.w0, msg);
          TEST_ASSERT_EQUAL_HEX16_MESSAGE(e.w2, w.w2, msg);
          if (got[j].mask) {
            TEST_ASSERT_EQUAL_HEX16_MESSAGE(e.code, w.code, msg);
            masked++;
          } else {
            TEST_ASSERT_EQUAL_HEX16_MESSAGE(e.code >> 11, PAL_SLINKY, msg);
          }
        }
        drawn += n != 0;
      }
    }
  }
  printf("slinky objects: %u slinky ticks drawn, %u mask MOs\n", drawn, masked);
  TEST_ASSERT_TRUE(drawn > 0 && masked > 0);
}

// ---------------------------------------------------------------- race start path

// machine race start (marble.cpp beginRace) on a cleared work RAM
static void beginRace(uint8_t race) {
  memset(ram, 0, sizeof(ram));
  Mem m(ram, race);
  marble_physics::startRace(m, race);
  marble_camera::start(m, race);
  marble_physics::project(m);
  marble_occlusion::enter(m, PLAYER);
}

// live slinky <=> exactly one type 4 draw list entry; at most the table's slinkies
static void checkListed(const Mem &m, uint8_t race, int16_t cam) {
  for (uint8_t i = 0; i < marble_enemies::NSLINKIES; i++) {
    const uint8_t want = m.rb(slinky(i) + SLOT) ? 1 : 0;
    if (listedCount(m, TYPE_SLINKY, i) == want) { continue; }
    char msg[80];
    snprintf(msg, sizeof(msg), "race %d cam %d: slinky %d live %d, draw list differs", race, cam,
             i, want);
    TEST_FAIL_MESSAGE(msg);
  }
}

// marble_slinky.py sweep: slinky spawns and removals in the camera loop, most live, per race
struct SweepCount { uint8_t spawns, removals, live; };
static const SweepCount SWEEP[RACES] = {{0, 0, 0}, {9, 9, 3}, {6, 6, 2}, {0, 0, 0}, {0, 0, 0},
                                        {8, 10, 4}};

// Race sweep (marble_slinky.py sweep): race start, then the camera over the whole race in
// 4 line steps, back, again, player idle; every enemy runs each tick. No abort, slinky spawns
// only at their table bands, a draw list entry iff live, objects within OBJS.
static void test_race_sweep(void) {
  for (uint8_t race = 0; race < RACES; race++) {
    beginRace(race);
    Mem m(ram, race);
    const int16_t top = m.desc().top;
    const int16_t range = m.desc().range;
    const int16_t n = range / SWEEP_STEP + 1;
    uint8_t spawns = 0, removals = 0, most = 0;
    uint32_t tick = 0;
    for (uint8_t pass = 0; pass < 3; pass++) {
      for (int16_t j = 0; j < n; j++) {
        int16_t step = pass == 1 ? n - 1 - j : j;  // there, back, there
        if (race == RACE_SILLY) { step = n - 1 - step; }
        const int16_t cam = top + SWEEP_STEP * step;
        uint8_t before[marble_enemies::NSLINKIES];
        for (uint8_t i = 0; i < marble_enemies::NSLINKIES; i++) {
          before[i] = m.rb(slinky(i) + SLOT);
        }
        mainTick(m, 0, 0, (uint32_t)(int32_t)cam, ++tick);
        marble_video::VideoState v = {};
        TEST_ASSERT_TRUE(marble_drawlist::build(m, cam, 24, v) <= marble_video::OBJS);

        uint8_t live = 0;
        for (uint8_t i = 0; i < marble_enemies::NSLINKIES; i++) {
          const uint32_t a = slinky(i);
          live += m.rb(a + SLOT) != 0;
          if (!before[i] && m.rb(a + SLOT)) {
            spawns++;
            const int16_t band = (int16_t)(cam - top) >> 4;
            TEST_ASSERT_TRUE_MESSAGE(band == m.sw(a + L_BAND_LO) || band == m.sw(a + L_BAND_HI),
                                     "slinky spawned outside its bands");
          }
          if (before[i] && !m.rb(a + SLOT)) { removals++; }
        }
        if (live > most) { most = live; }
        checkListed(m, race, cam);
      }
    }
    char msg[60];
    snprintf(msg, sizeof(msg), "race %d: spawns, removals, most live", race);
    TEST_ASSERT_EQUAL_UINT8_MESSAGE(SWEEP[race].spawns, spawns, msg);
    TEST_ASSERT_EQUAL_UINT8_MESSAGE(SWEEP[race].removals, removals, msg);
    TEST_ASSERT_EQUAL_UINT8_MESSAGE(SWEEP[race].live, most, msg);
  }
}

// camera stepped down the race from its top until a slinky lives; its index, -1 if none
static int8_t firstSlinky(Mem &m, int16_t &cam, uint32_t &tick) {
  const int16_t top = m.desc().top;
  const int16_t range = m.desc().range;
  for (cam = top; cam <= top + range; cam += SWEEP_STEP) {
    mainTick(m, 0, 0, (uint32_t)(int32_t)cam, ++tick);
    for (uint8_t i = 0; i < marble_enemies::NSLINKIES; i++) {
      if (m.rb(slinky(i) + SLOT)) { return (int8_t)i; }
    }
  }
  return -1;
}

// the player put on slinky a (position, ground, zone), standing still
static void placeOn(Mem &m, uint32_t a) {
  m.wl(PLAYER + 0x00, 0);
  m.wl(PLAYER + 0x04, 0);
  m.wl(PLAYER + PX, m.rl(a + PX));
  m.wl(PLAYER + PY, m.rl(a + PY));
  m.wl(PLAYER + PZ, m.rl(a + PZ));
  m.wb(PLAYER + ZONE, m.rb(a + ZONE));
}

// In every slinky race a slinky catches the still marble put on it: player EATEN, HIDDEN, LOST,
// then rolling again; the draw list stays consistent. A race switch while the player is held
// starts as from a cleared work RAM.
static void test_eat_and_switch(void) {
  static const uint8_t SLINKY_RACES[] = {1, 2, 5};
  for (uint8_t race : SLINKY_RACES) {
    beginRace(race);
    Mem m(ram, race);
    int16_t cam = 0;
    uint32_t tick = 0;
    const int8_t live = firstSlinky(m, cam, tick);
    TEST_ASSERT_TRUE_MESSAGE(live >= 0, "no slinky spawned");

    placeOn(m, slinky((uint8_t)live));
    bool seen[ST_HIDDEN + 1] = {};
    uint16_t k = 0;
    for (; k < EAT_TICKS; k++) {
      mainTick(m, 0, 0, (uint32_t)(int32_t)cam, ++tick);
      const uint8_t st = marble_physics::state(m);
      if (st <= ST_HIDDEN) { seen[st] = true; }
      checkListed(m, race, cam);
      if (seen[marble_physics::LOST] && st == marble_physics::ROLL) { break; }
    }
    char msg[60];
    snprintf(msg, sizeof(msg), "race %d: eaten, hidden, lost, rolling", race);
    TEST_ASSERT_TRUE_MESSAGE(seen[marble_physics::EATEN] && seen[ST_HIDDEN], msg);
    TEST_ASSERT_TRUE_MESSAGE(k < EAT_TICKS, msg);

    // eaten again, switch race while the player is held
    placeOn(m, slinky((uint8_t)live));
    for (k = 0; k < EAT_TICKS && marble_physics::state(m) != ST_HIDDEN; k++) {
      mainTick(m, 0, 0, (uint32_t)(int32_t)cam, ++tick);
    }
    TEST_ASSERT_EQUAL_UINT8(ST_HIDDEN, marble_physics::state(m));
    const uint8_t next = (race + 1) % RACES;
    beginRace(next);
    static uint8_t clean[marble_physics::RAM_SIZE];
    memcpy(clean, ram, sizeof(ram));
    beginRace(next);
    TEST_ASSERT_EQUAL_MEMORY(clean, ram, sizeof(ram));
    Mem n(ram, next);
    TEST_ASSERT_EQUAL_UINT8(marble_physics::ROLL, marble_physics::state(n));
    for (uint8_t i = 0; i < marble_enemies::NSLINKIES; i++) {
      TEST_ASSERT_EQUAL_UINT8(i, n.rb(slinky(i) + IDX));
      TEST_ASSERT_EQUAL_UINT8(n.rb(slinky(i) + SLOT) ? 1 : 0, listedCount(n, TYPE_SLINKY, i));
    }
  }
}
#endif

int main(int, char **) {
  UNITY_BEGIN();
#ifdef HAVE_ROM
  Arena::init();
  Arena::reserve(&marble_arena_plan);  // like switchTo()
  marble_physics::loadRom();
  RUN_TEST(test_replay_slinkies);
  RUN_TEST(test_slinky_objects);
  RUN_TEST(test_race_sweep);
  RUN_TEST(test_eat_and_switch);
#else
  printf("marble_rom.h missing (run romconv ./convert.sh marble): slinky tests skipped\n");
#endif
  return UNITY_END();
}
